package com.musicplayer.ui.screens.nowplaying

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.musicplayer.data.repository.MusicRepository
import com.musicplayer.domain.model.Track
import com.musicplayer.service.PlayerController
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject

data class NowPlayingUiState(
    val currentTrack: Track? = null,
    val isPlaying: Boolean = false,
    val volumeLevel: Int = 35,
    val progressMs: Long = 0L,
    val durationMs: Long = 0L,
    val isShuffled: Boolean = false,
    val repeatMode: Int = 0,
    val isFavorite: Boolean = false,
)

@HiltViewModel
class NowPlayingViewModel @Inject constructor(
    private val repo: MusicRepository,
    private val playerController: PlayerController,
) : ViewModel() {

    // Optimistic override for the favorite state so the heart icon responds instantly.
    // Null means "use whatever the Track object says". Reset whenever the track changes.
    private val _favoriteOverride = MutableStateFlow<Boolean?>(null)

    val uiState: StateFlow<NowPlayingUiState> = combine(
        playerController.state,
        _favoriteOverride,
    ) { ps, favoriteOverride ->
        NowPlayingUiState(
            currentTrack = ps.currentTrack,
            isPlaying = ps.isPlaying,
            volumeLevel = ps.volumeLevel,
            progressMs = ps.progressMs,
            durationMs = ps.durationMs,
            isShuffled = ps.isShuffled,
            repeatMode = ps.repeatMode,
            isFavorite = favoriteOverride ?: ps.currentTrack?.isFavorite ?: false,
        )
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.WhileSubscribed(5_000),
        initialValue = NowPlayingUiState(),
    )

    init {
        // Clear the override whenever the playing track changes.
        viewModelScope.launch {
            playerController.state
                .map { it.currentTrack?.id }
                .distinctUntilChanged()
                .collect { _favoriteOverride.value = null }
        }
    }

    fun toggleFavorite() = viewModelScope.launch {
        val track = playerController.state.value.currentTrack ?: return@launch
        val newValue = !(_favoriteOverride.value ?: track.isFavorite)
        _favoriteOverride.value = newValue  // optimistic — icon flips immediately
        repo.setFavorite(track.id, newValue)
    }

    fun setVolumeLevel(level: Int) {
        playerController.setVolume(level)
    }

    fun seekTo(positionMs: Long) {
        playerController.seekTo(positionMs)
    }

    fun togglePlayPause() {
        playerController.togglePlayPause()
    }

    fun next() {
        playerController.next()
    }

    fun previous() {
        playerController.previous()
    }

    fun toggleShuffle() {
        playerController.setShuffleEnabled(!playerController.state.value.isShuffled)
    }

    fun cycleRepeat() {
        val next = (playerController.state.value.repeatMode + 1) % 3
        playerController.setRepeatMode(next)
    }
}

